  const variables=()=>{const chat=targetBot.groups.find(g=>g.chat_id===$('messageChat').value);const now=new Date();return{...($('templateName')?.value?{name:$('templateName').value}:{}),...($('templateUser')?.value?{user_id:$('templateUser').value}:{}),chat_title:chat?.title || '',bot_name:targetBot.name,date:new Intl.DateTimeFormat('fa-IR',{timeZone:'Asia/Tehran',dateStyle:'short'}).format(now),time:new Intl.DateTimeFormat('fa-IR',{timeZone:'Asia/Tehran',hour:'2-digit',minute:'2-digit'}).format(now)};};
  $('previewMessage').onclick=()=>{const data=new FormData(f);$('messagePreview').replaceChildren();const text=document.createElement('div');text.textContent=renderTemplatePreview(data.get('text')||data.get('question')||methods[$('messageMethod').value][0],variables());$('messagePreview').append(text);for(const row of keypad?.preview() || []){const div=document.createElement('div');div.className='keypad-preview-row';for(const label of row){const span=document.createElement('span');span.className='keypad-preview-button';span.textContent=label || 'دکمهٔ بدون متن';div.append(span);}$('messagePreview').append(div);}};
